/* #monster command - use special monster ability while polymorphed */
/**
 * @returns {Promise<number>} int
 */
export async function domonability() {   // cmd.c:890
    const uptr = gy.youmonst.data;
    const might_hide = is_hider(uptr) || hides_under(uptr) ? 1 : 0;
    let c = 0;
    if (might_hide && webmaker(uptr)) {
        c = await yn_function($C`Hide [h] or spin a web [s]?`,
            new $c.Ptr(hidespinchars, 0), 113, TRUE);
        if (c === 113 || c === 27) {
            return ECMD.OK;
        }
    }
    if (can_breathe(uptr)) {
        return await dobreathe();
    } else if (attacktype(uptr, AT.SPIT)) {
        return await dospit();
    } else if (uptr.mlet === S.NYMPH) {
        return await doremove();
    } else if (attacktype(uptr, AT.GAZE)) {
        return await dogaze();
    } else if (is_were(uptr)) {
        return await dosummon();
    } else if (c ? c === 104 : might_hide) {
        return await dohide();
    } else if (c ? c === 115 : webmaker(uptr)) {
        return await dospinweb();
    } else if (is_mind_flayer(uptr)) {
        return await domindblast();
    } else if (u.umonnum === PM.GREMLIN) {
        if (svl.level.locations[u.ux][u.uy].typ === FOUNTAIN) {
            if (await split_mon(gy.youmonst, null)) {
                await dryup(u.ux, u.uy, TRUE);
            }
        } else if (is_pool(u.ux, u.uy)) {
            /* is_pool: might be wearing water walking boots or amulet of
               magical breathing */
            await split_mon(gy.youmonst, null);
        } else {
            await There($C`is no fountain here.`);
        }
    } else if (is_unicorn(uptr)) {
        await use_unicorn_horn(null);
        return ECMD.TIME;
    } else if (uptr.msound === MS.SHRIEK) {
        await You($C`shriek.`);
        if (u.uburied) {
            await pline($C`Unfortunately sound does not carry well through rock.`);
        } else {
            await aggravate();
        }
    } else if (is_vampire(uptr) || is_vampshifter(gy.youmonst)) {
        return await dopoly();
    } else if (u.usteed && can_breathe(u.usteed.data)) {
        await pet_ranged_attk(u.usteed, TRUE);
        return ECMD.TIME;
    } else if (Upolyd()) {
        await pline($C`Any special ability you may have is purely reflexive.`);
    } else {
        await You($C`don't have a special ability in your normal form!`);
    }
    return ECMD.OK;
}
