/* #terrain command -- show known map, inspired by crawl's '|' command */
/**
 * @returns {Promise<number>} int
 */
async function doterrain() {   // cmd.c:1098
    let sel = [null], any = new $T.any();
    const clr = NO_COLOR;
    /* this used to be done each time vision was recalculated, so would
       always be up to date (hopefully); now we do it on demand instead */
    await recalc_mapseen();
    /*
     * normal play: choose between known map without mons, obj, and traps
     *  (to see underlying terrain only), or
     *  known map without mons and objs (to see traps under mons and objs), or
     *  known map without mons (to see objects under monsters);
     * explore mode: normal choices plus full map (w/o mons, objs, traps);
     * wizard mode: normal and explore choices plus
     *  a dump of the internal levl[][].typ codes w/ level flags, or
     *  a legend for the levl[][].typ codes dump
     */
    const men = await create_nhwindow()(NHW.MENU);
    await start_menu()(men, MENU.BEHAVE_STANDARD);
    any.$copyFrom(cg.zeroany);
    any.a_int = 1;
    await add_menu(men, nul_glyphinfo, any, 0, 0, ATR.NONE, clr,
        $C`known map without monsters, objects, and traps`,
        MENU.ITEMFLAGS_SELECTED);
    any.a_int = 2;
    await add_menu(men, nul_glyphinfo, any, 0, 0, ATR.NONE,
        clr, $C`known map without monsters and objects`,
        MENU.ITEMFLAGS_NONE);
    any.a_int = 3;
    await add_menu(men, nul_glyphinfo, any, 0, 0, ATR.NONE,
        clr, $C`known map without monsters`,
        MENU.ITEMFLAGS_NONE);
    if (discover() || wizard()) {
        any.a_int = 4;
        await add_menu(men, nul_glyphinfo, any, 0, 0, ATR.NONE,
            clr, $C`full map without monsters, objects, and traps`,
            MENU.ITEMFLAGS_NONE);
        if (wizard()) {
            any.a_int = 5;
            await add_menu(men, nul_glyphinfo, any, 0, 0, ATR.NONE,
                clr, $C`internal levl[][].typ codes in base-36`,
                MENU.ITEMFLAGS_NONE);
            any.a_int = 6;
            await add_menu(men, nul_glyphinfo, any, 0, 0, ATR.NONE,
                clr, $C`legend of base-36 levl[][].typ codes`,
                MENU.ITEMFLAGS_NONE);
        }
    }
    await end_menu()(men, $C`View which?`);
    const n = await select_menu(men, PICK.ONE, new $c.Ptr(sel, 0));
    await destroy_nhwindow()(men);
    /*
     * n <  0: player used ESC to cancel;
     * n == 0: preselected entry was explicitly chosen and got toggled off;
     * n == 1: preselected entry was implicitly chosen via <space>|<enter>;
     * n == 2: another entry was explicitly chosen, so skip preselected one.
     */
    let which = n < 0 ? -1 : n === 0 ? 1 : $c.radd(sel[0], 0).item.a_int;
    if (n > 1 && which === 1) {
        which = $c.radd(sel[0], 1).item.a_int;
    }
    if (n > 0) {
        $c.free(sel[0]);
    }
    switch (which) {
        case 1:
            /* known map */
            await reveal_terrain(TER.MAP);
            break;
        case 2:
            /* known map with known traps */
            await reveal_terrain(TER.MAP | TER.TRP);
            break;
        case 3:
            /* known map with known traps and objects */
            await reveal_terrain(TER.MAP | TER.TRP | TER.OBJ);
            break;
        case 4:
            /* full map */
            await reveal_terrain(TER.MAP | TER.FULL);
            break;
        case 5:
            /* map internals */
            await wiz_map_levltyp();
            break;
        case 6:
            /* internal details */
            await wiz_levltyp_legend();
            break;
        default:
            break;
    }
    return ECMD.OK;   /* no time elapses */
}
