/* #repeat */
/**
 * @returns {Promise<number>} int
 */
export async function do_repeat() {   // cmd.c:1638
    let res = ECMD.OK;
    if (!gi.in_doagain) {
        if (!cmdq_peek(CQ_REPEAT)) {
            await Norep($C`There is no command available to repeat.`);
            return ECMD.FAIL;
        }
        const repeat_copy = await cmdq_copy(CQ_REPEAT);
        gi.in_doagain = TRUE;
        await rhack(0);   /* read and execute command */
        gi.in_doagain = FALSE;
        cmdq_clear(CQ_REPEAT);
        gc.command_queue[CQ_REPEAT] = repeat_copy;
        iflags.menu_requested = FALSE;
        if (svc.context.move) {
            res = ECMD.TIME;
        }
    }
    return res;
}
